/// Entries in a dispute timeline.
enum DisputeAction: String, Codable, Hashable, Sendable, CaseIterable {
    case opened = "opened"
    case reply = "reply"
    case evidenceRequested = "evidence_requested"
    case evidenceAdded = "evidence_added"
    case reviewStarted = "review_started"
    case decision = "decision"
    case withdrawn = "withdrawn"
    /// A value this build does not know yet (decoded from JSON, never sent).
    case unknown = "unknown"

    /// Every value the contract defines (without `.unknown`), in contract order.
    static var allCases: [DisputeAction] {
        return [.opened, .reply, .evidenceRequested, .evidenceAdded, .reviewStarted, .decision, .withdrawn]
    }

    init(from decoder: Decoder) throws {
        let container: SingleValueDecodingContainer = try decoder.singleValueContainer()
        let raw: String = try container.decode(String.self)
        self = DisputeAction(rawValue: raw) ?? .unknown
    }

    func encode(to encoder: Encoder) throws {
        var container: SingleValueEncodingContainer = encoder.singleValueContainer()
        try container.encode(rawValue)
    }

    /// False for `.unknown`.
    var isKnown: Bool {
        return self != .unknown
    }

    /// UI label from the contract ("Views still counting").
    var label: String {
        switch self {
        case .opened: return "Opened"
        case .reply: return "Reply"
        case .evidenceRequested: return "Evidence requested"
        case .evidenceAdded: return "Evidence added"
        case .reviewStarted: return "Review started"
        case .decision: return "Decision"
        case .withdrawn: return "Withdrawn"
        case .unknown: return "Unknown"
        }
    }

    /// Colour tone from the contract; map to a design-system tone with `.flowdTone`.
    var tone: ContractTone {
        switch self {
        case .opened: return .info
        case .reply: return .neutral
        case .evidenceRequested: return .ember
        case .evidenceAdded: return .info
        case .reviewStarted: return .accent
        case .decision: return .mint
        case .withdrawn: return .neutral
        case .unknown: return .neutral
        }
    }

    /// Plain-English meaning from the contract, when it has one.
    var meaning: String? {
        switch self {
        case .opened: return "The dispute was opened."
        case .reply: return "A person replied."
        case .evidenceRequested: return "Ops asked for evidence."
        case .evidenceAdded: return "A party added evidence."
        case .reviewStarted: return "Ops started the review."
        case .decision: return "Ops decided."
        case .withdrawn: return "The opener withdrew."
        case .unknown: return nil
        }
    }
}
